export function MessageThread({ name = "Kevin", accent = "#0a84ff", autoplay = true, appearance = "auto", replayKey = 0, onSend, onReact, className = "", style }: MessageThreadProps) {
  const reduced = !!useReducedMotion();
  const [messages, setMessages] = useState<Message[]>(history), [typing, setTyping] = useState<string | null>(null), [read, setRead] = useState(true);
  const [menu, setMenu] = useState<{ id: string; left: number; top: number; auto: boolean } | null>(null), [hot, setHot] = useState(-1);
  const [draft, setDraft] = useState(""), [focusId, setFocusId] = useState("m5"), [spoken, setSpoken] = useState("");
  const panel = useRef<HTMLDivElement>(null), scroller = useRef<HTMLDivElement>(null), holds = useRef<Record<string, HTMLDivElement | null>>({}), picks = useRef<(HTMLButtonElement | null)[]>([]);
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]), tour = useRef<ReturnType<typeof setTimeout>[]>([]), press = useRef<{ timer: ReturnType<typeof setTimeout>; x: number; y: number } | null>(null);
  const counter = useRef(0), morphs = useRef(new Set<string>()), touring = useRef(false), latest = useRef({ messages, typing });
  latest.current = { messages, typing };
  const pinned = useRef(true), opened = useRef(false);
  opened.current = !!menu;
  const tint = /^#[\da-f]{6}$/i.test(accent) ? accent : "#0a84ff", who = name.trim() || "Kevin";

  const later = (list: typeof timers, run: () => void, delay: number) => { list.current.push(setTimeout(run, delay)); };
  const clear = (list: typeof timers) => { list.current.forEach(clearTimeout); list.current = []; };
  const arrive = (id: string, text: string) => {
    morphs.current.add(id);
    setTyping(null);
    setMessages(previous => [...previous, { id, from: "them", text, reactions: [] }]);
    setSpoken(`${who}: ${text}`);
  };
  // Choosing the reaction that is already there removes it.
  const choose = (id: string, emoji: string, by: Who = "me") => {
    const current = latest.current.messages.find(message => message.id === id);
    const next = current?.reactions.some(item => item.by === by && item.emoji === emoji) ? null : emoji;
    setMessages(previous => previous.map(message => message.id === id ? react(message, by, next) : message));
    if (by === "me") onReact?.(id, next);
  };
  const close = (refocus: boolean) => {
    const id = menu?.id;
    setMenu(null); setHot(-1);
    if (refocus && id) holds.current[id]?.focus({ preventScroll: true });
  };
  const open = (id: string, auto = false) => {
    const hold = holds.current[id], box = panel.current, list = scroller.current;
    if (!hold || !box || !list) return;
    // Bring the whole bubble between the bars before measuring, so the lifted copy is never cut off.
    let rect = hold.getBoundingClientRect(), frame = box.getBoundingClientRect();
    const above = rect.top - frame.top - header - fade, below = frame.bottom - footer - fade - rect.bottom;
    if (above < 0) list.scrollTop += above; else if (below < 0) list.scrollTop -= below;
    rect = hold.getBoundingClientRect(); frame = box.getBoundingClientRect();
    const mine = latest.current.messages.find(message => message.id === id)?.from === "me";
    const left = Math.max(12, Math.min(frame.width - menuWidth - 12, mine ? rect.right - frame.left - menuWidth : rect.left - frame.left));
    const top = rect.top - frame.top - menuHeight - 10 >= 12 ? rect.top - frame.top - menuHeight - 10 : rect.bottom - frame.top + 10;
    setFocusId(id); setMenu({ id, left, top, auto }); setHot(-1);
  };
  const send = () => {
    const text = draft.trim();
    if (!text) return;
    clear(timers);
    if (typing) { morphs.current.delete(typing); setTyping(null); }
    const id = `s${++counter.current}`, reply = `r${counter.current}`;
    setMessages(previous => [...previous, { id, from: "me", text: text.slice(0, 600), reactions: [] }]);
    setDraft(""); setRead(false); setFocusId(id); onSend?.(text);
    later(timers, () => setRead(true), 900);
    later(timers, () => setTyping(reply), 1400);
    // replies[0] is the demo's own reply, so a sent message starts from the next one.
    const answer = replies[1 + (counter.current - 1) % (replies.length - 1)];
    later(timers, () => arrive(reply, answer), 2900);
  };
  // The first interaction ends the tour and settles whatever it was in the middle of.
  const settle = () => {
    if (!touring.current) return;
    touring.current = false; clear(tour);
    if (latest.current.typing === "a1") arrive("a1", replies[0]);
    setMenu(current => current?.auto ? null : current); setHot(-1);
  };

  useEffect(() => {
    clear(timers); clear(tour); morphs.current.clear();
    setMenu(null); setHot(-1); setDraft(""); setRead(true); setFocusId("m5"); setSpoken("");
    const final = () => setMessages([...history().map(message => message.id === "m2" ? react(message, "me", "❤️") : message.id === "m4" ? react(message, "them", "🔥") : message), { id: "a1", from: "them", text: replies[0], reactions: [] }]);
    if (!autoplay || reduced) { setTyping(null); if (autoplay) final(); else setMessages(history()); return; }
    setMessages(history()); setTyping(null); touring.current = true;
    later(tour, () => setTyping("a1"), 900);
    later(tour, () => arrive("a1", replies[0]), 2600);
    later(tour, () => open("m2", true), 4000);
    later(tour, () => setHot(2), 4500);
    later(tour, () => setHot(0), 4950);
    later(tour, () => { choose("m2", "❤️"); setMenu(null); setHot(-1); }, 5500);
    later(tour, () => { choose("m4", "🔥", "them"); touring.current = false; }, 6700);
    return () => { clear(timers); clear(tour); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoplay, reduced, replayKey]);
  useEffect(() => () => { clear(timers); clear(tour); if (press.current) clearTimeout(press.current.timer); }, []);
  // While the reader is at the bottom, stay there as the thread grows: new messages, the typing bubble and reactions all add height.
  useLayoutEffect(() => {
    const list = scroller.current, content = list?.firstElementChild;
    if (!list || !content) return;
    list.scrollTop = list.scrollHeight;
    const watch = () => { pinned.current = list.scrollHeight - list.scrollTop - list.clientHeight < 32; };
    const follow = new ResizeObserver(() => { if (pinned.current && !opened.current) list.scrollTo({ top: list.scrollHeight, behavior: reduced ? "auto" : "smooth" }); });
    list.addEventListener("scroll", watch, { passive: true }); follow.observe(content);
    return () => { list.removeEventListener("scroll", watch); follow.disconnect(); };
  }, [reduced]);
  useEffect(() => {
    if (!menu || menu.auto) return;
    const checked = messages.find(message => message.id === menu.id)?.reactions.find(item => item.by === "me")?.emoji;
    picks.current[Math.max(0, emojis.findIndex(item => item.emoji === checked))]?.focus({ preventScroll: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [menu?.id]);

  const items = [...messages.map(message => ({ id: message.id, from: message.from, message })), ...(typing ? [{ id: typing, from: "them" as Who, message: undefined }] : [])];
  const lastMine = messages[messages.length - 1]?.from === "me" ? messages[messages.length - 1].id : null;
  const active = menu ? messages.find(message => message.id === menu.id) : undefined;
  const spring = reduced ? { duration: 0 } : { type: "spring" as const, duration: .42, bounce: .22 };
  const pressStart = (id: string) => (event: ReactPointerEvent) => {
    if (event.button !== 0 || menu) return;
    press.current = { x: event.clientX, y: event.clientY, timer: setTimeout(() => { press.current = null; open(id); }, 380) };
  };
  const pressMove = (event: ReactPointerEvent) => { if (press.current && Math.hypot(event.clientX - press.current.x, event.clientY - press.current.y) > 8) pressEnd(); };
  const pressEnd = () => { if (press.current) { clearTimeout(press.current.timer); press.current = null; } };
  const bubbleKeys = (id: string) => (event: KeyboardEvent<HTMLDivElement>) => {
    const ids = messages.map(message => message.id), at = ids.indexOf(id);
    if (event.key === "Enter" || event.key === " ") { event.preventDefault(); open(id); }
    else if (event.key === "ArrowUp" || event.key === "ArrowDown" || event.key === "Home" || event.key === "End") {
      event.preventDefault();
      const next = ids[event.key === "Home" ? 0 : event.key === "End" ? ids.length - 1 : Math.max(0, Math.min(ids.length - 1, at + (event.key === "ArrowUp" ? -1 : 1)))];
      setFocusId(next); holds.current[next]?.focus(); holds.current[next]?.scrollIntoView({ block: "nearest" });
    }
  };
  const menuKeys = (event: KeyboardEvent<HTMLDivElement>) => {
    const at = picks.current.indexOf(document.activeElement as HTMLButtonElement);
    if (event.key === "Escape") { event.preventDefault(); close(true); }
    else if (event.key === "Tab") { event.preventDefault(); close(true); }
    else if (event.key === "ArrowRight" || event.key === "ArrowLeft") { event.preventDefault(); picks.current[(at + (event.key === "ArrowRight" ? 1 : -1) + emojis.length) % emojis.length]?.focus(); }
    else if (event.key === "Home" || event.key === "End") { event.preventDefault(); picks.current[event.key === "Home" ? 0 : emojis.length - 1]?.focus(); }
  };

  return <div className={`nmt-stage ${className}`} data-menu={menu ? "open" : "closed"} onPointerDownCapture={settle} onKeyDownCapture={settle}
    style={{ colorScheme: appearance === "auto" ? undefined : appearance, "--nmt-accent": tint, ...style } as CSSProperties}>
    <style>{css}</style>
    <div ref={panel} className="nmt-panel" role="group" aria-label={`Conversation with ${who}`}>
      <div className="nmt-head"><img className="nmt-face" src={photos.avatar} alt="" draggable={false} /><span className="nmt-name">{who}<Chevron /></span></div>
      <motion.div ref={scroller} className="nmt-scroll" layoutScroll>
        <div>
        <p className="nmt-date"><b>Today</b> 9:41 AM</p>
        <div role="log" aria-label="Messages">
          <LayoutGroup>
            <AnimatePresence initial={false} mode="popLayout">
              {items.flatMap((item, index) => {
                const previous = items[index - 1], next = items[index + 1], message = item.message;
                const first = previous?.from !== item.from, last = next?.from !== item.from, lifted = menu?.id === item.id;
                const reactions = message?.reactions ?? [], morph = morphs.current.has(item.id);
                const status = item.id === lastMine ? [<motion.div key="nmt-status" className="nmt-status" layout={reduced ? false : "position"} transition={spring}
                  initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, transition: { duration: reduced ? 0 : .12 } }}>
                  <AnimatePresence initial={false} mode="popLayout">
                    <motion.span key={read ? "read" : "sent"} initial={{ opacity: 0, y: reduced ? 0 : 4 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} transition={{ duration: reduced ? 0 : .2, ease }}>
                      {read ? <><b>Read</b>9:42 AM</> : "Delivered"}
                    </motion.span>
                  </AnimatePresence>
                </motion.div>] : [];
                return [<motion.div key={item.id} className="nmt-row" data-from={item.from} data-first={first && index > 0} data-reacted={reactions.length > 0}
                  layout={reduced ? false : "position"} transition={spring} style={{ zIndex: lifted ? 3 : undefined }}
                  initial={morph ? false : { opacity: 0, y: 18, scale: .96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, scale: .9, transition: { duration: reduced ? 0 : .14 } }}>
                  <div ref={node => { if (message) holds.current[item.id] = node; }} className="nmt-hold" data-active={lifted}
                    tabIndex={message ? (item.id === focusId ? 0 : -1) : undefined} role={message ? "button" : undefined} aria-haspopup={message ? "menu" : undefined} aria-expanded={message ? lifted : undefined}
                    aria-label={message ? `${item.from === "me" ? "You" : who}: ${message.photo ? "Photo of a beach at sunset" : message.text}${reactions.length ? `. Reactions: ${reactions.map(reaction => `${reaction.emoji} from ${reaction.by === "me" ? "you" : who}`).join(", ")}` : ""}` : undefined}
                    onFocus={() => message && setFocusId(item.id)} onKeyDown={message ? bubbleKeys(item.id) : undefined}
                    onPointerDown={message ? pressStart(item.id) : undefined} onPointerMove={pressMove} onPointerUp={pressEnd} onPointerCancel={pressEnd} onPointerLeave={pressEnd}
                    onContextMenu={message ? event => { event.preventDefault(); pressEnd(); open(item.id); } : undefined} onDoubleClick={message ? () => open(item.id) : undefined}>
                    <motion.div layoutId={`nmt-${item.id}`} transition={spring} className={`nmt-bubble${message?.photo ? " nmt-photo" : ""}${message ? "" : " nmt-typing"}`} data-tail={message && !message.photo && last ? item.from : undefined}>
                      {!message ? <><i /><i /><i /><span className="nmt-sr">{who} is typing</span></>
                        : message.photo ? <img src={photos.beach} alt="" draggable={false} />
                          : <motion.span className="nmt-text" initial={morph ? { opacity: 0 } : false} animate={{ opacity: 1 }} transition={{ duration: reduced ? 0 : .2, delay: reduced ? 0 : .12 }}>{message.text}</motion.span>}
                    </motion.div>
                    <span className="nmt-badges" aria-hidden="true">
                      <AnimatePresence initial={false}>
                        {reactions.map(reaction => <motion.span key={`${reaction.by}-${reaction.emoji}`} className="nmt-badge" data-by={reaction.by}
                          initial={{ opacity: 0, scale: reduced ? 1 : .2, rotate: reduced ? 0 : -24 }} animate={{ opacity: 1, scale: 1, rotate: 0 }} exit={{ opacity: 0, scale: reduced ? 1 : .4 }}
                          transition={reduced ? { duration: 0 } : { type: "spring", duration: .5, bounce: .5 }}>{reaction.emoji}</motion.span>)}
                      </AnimatePresence>
                    </span>
                  </div>
                </motion.div>, ...status];
              })}
            </AnimatePresence>
          </LayoutGroup>
        </div>
        </div>
      </motion.div>
      <div className="nmt-foot">
        <div className="nmt-field">
          <input className="nmt-input" value={draft} placeholder="Message" aria-label={`Message ${who}`} enterKeyHint="send" autoComplete="off"
            onChange={event => setDraft(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && !event.nativeEvent.isComposing) { event.preventDefault(); send(); } }} />
          <AnimatePresence>
            {draft.trim() && <motion.button type="button" className="nmt-send" aria-label="Send" onClick={send}
              initial={{ opacity: 0, scale: reduced ? 1 : .4 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: reduced ? 1 : .4 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: .32, bounce: .4 }}><Arrow /></motion.button>}
          </AnimatePresence>
        </div>
      </div>
      <AnimatePresence>
        {menu && <motion.div key="veil" className="nmt-veil" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: reduced ? 0 : .18, ease }} onPointerDown={() => close(false)} />}
        {menu && <motion.div key="menu" className="nmt-menu" role="menu" aria-label="React" style={{ left: menu.left, top: menu.top, transformOrigin: active?.from === "me" ? "100% 100%" : "0 100%" }} onKeyDown={menuKeys}
          initial={{ opacity: 0, scale: reduced ? 1 : .6 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: reduced ? 1 : .8 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: .36, bounce: .3 }}>
          {emojis.map((item, index) => {
            const checked = !!active?.reactions.some(reaction => reaction.by === "me" && reaction.emoji === item.emoji);
            return <motion.button key={item.emoji} ref={node => { picks.current[index] = node; }} type="button" className="nmt-pick" role="menuitemradio" aria-checked={checked} aria-label={item.label} data-hot={hot === index}
              initial={{ opacity: 0, y: reduced ? 0 : 10, scale: reduced ? 1 : .5 }} animate={{ opacity: 1, y: 0, scale: 1 }} transition={reduced ? { duration: 0 } : { type: "spring", duration: .4, bounce: .45, delay: index * .025 }}
              onClick={() => { choose(menu.id, item.emoji); close(!menu.auto); }}><span>{item.emoji}</span></motion.button>;
          })}
        </motion.div>}
      </AnimatePresence>
      <span className="nmt-sr" aria-live="polite">{spoken}</span>
    </div>
  </div>;
}

